// A GitHub webhook per repository: a maintainer binds it through the generated endpoint, and each push records the ref.

import { app } from '../app-kit'
import { Push } from '../schemas'

export const github = app.webhook('/hooks/github', { scheme: 'github-sha256', boundTo: 'repo', actions: ['repos.write'], input: Push, maxBytes: 262144 })
	.handle(async ({ input, ctx }) => {
		const repo = ctx.db.on(ctx.refs['repos.write'])
		const row = await repo.getForUpdate()
		await repo.update({ last_push: input.ref }, { expectVersion: row.version })
	})

/** A nightly pass over every repository, with its own time limit. */
export const nightly = app.cron('0 3 * * *', { actions: ['repos.read'], scope: 'app', timeout: '5m', retries: 1 }).handle(async () => {})

