import { defineVocabulary } from '@fabrika/app/contract'

export const vocabulary = defineVocabulary({
	app: 'hooks',
	dimensions: { repo: { creator: 'maintainer', members: { manage: 'repos.admin', list: 'repos.read' } } },
	actions: {
		'repos.read': 'Read a repository and its pushes',
		'repos.write': 'Record a push to a repository',
		'repos.admin': 'Connect a repository to GitHub and manage its maintainers',
		'repos.create': 'Start a repository',
	},
	roles: {
		starter: { grants: ['repos.create'] },
		maintainer: { grants: ['repos.read', 'repos.write', 'repos.admin'], member: { scope: 'repo', assignableBy: ['maintainer'] } },
	},
})
